<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { api } from '../api';
type User={wechatId:string;nickname:string|null;families:{name:string;role:string}[];createdAt:string}; const keyword=ref(''), users=ref<User[]>([]), total=ref(0), loading=ref(false);
async function load(page=1){loading.value=true;try{const {data}=await api.get('/admin/users',{params:{page,pageSize:20,keyword:keyword.value}});users.value=data.items;total.value=data.total;}catch(error:any){ElMessage.error(error.response?.data?.message||'读取用户失败');}finally{loading.value=false;}} onMounted(load);
</script>
<template><section><h1>用户与家庭</h1><p class="muted">数据直接来自 PostgreSQL，支持按昵称、微信标识或家庭名称检索。</p><el-card><div class="toolbar"><el-input v-model="keyword" placeholder="搜索用户或家庭" clearable @keyup.enter="load()"/><el-button type="primary" @click="load()">查询</el-button></div><el-table :data="users" v-loading="loading"><el-table-column label="用户昵称"><template #default="{row}">{{row.nickname||'未设置昵称'}}</template></el-table-column><el-table-column prop="wechatId" label="微信标识"/><el-table-column label="所属家庭"><template #default="{row}">{{row.families.map((f:any)=>`${f.name}（${f.role}）`).join('、')||'未加入家庭'}}</template></el-table-column><el-table-column label="注册时间"><template #default="{row}">{{new Date(row.createdAt).toLocaleString()}}</template></el-table-column></el-table><el-pagination v-if="total" layout="total, prev, pager, next" :total="total" class="pagination" @current-change="load"/></el-card></section></template>
